import { test, expect } from '@playwright/test';

test.describe('Sauce Demo Store Login Functionality', () => {
  test('should log in successfully with valid credentials', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/login');
    await page.fill('#username', 'standard_user');
    await page.fill('#password', 'secret_sauce');
    await page.click('#login-button');
    await expect(page).toHaveURL(/.*inventory.html/);
    await expect(page.locator('.title')).toBeVisible();
    await expect(page.locator('.title')).toHaveText('Products');
  });

  test('should not change URL or page title on login failure', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/login');
    await page.fill('#username', 'wrong_user');
    await page.fill('#password', 'wrong_password');
    await page.click('#login-button');
    await expect(page).toHaveURL('https://www.saucedemo.com/login');
    await expect(page.locator('.title')).toBeVisible();
    await expect(page.locator('.title')).toHaveText('Products');
  });
});
